package org.sportssimulation.virtualrun;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.net.Uri;import android.widget.*;import android.view.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
/** Public AMap web page in a separate view. The bridge carries coordinates only. */
public final class LiveMapActivity extends Activity {
 private String pageUserAgent="";private WebView web;private TextView status;private Button accept;private String selection="[]",configuration="{}",bootstrap="";private boolean ready=false;
 private static boolean navigationHost(String h){return "m.amap.com".equals(h)||"uri.amap.com".equals(h)||"ditu.amap.com".equals(h);}
 private static boolean resourceHost(String h){return h!=null&&(navigationHost(h)||h.endsWith(".amap.com")||h.endsWith(".autonavi.com")||h.endsWith(".alicdn.com")||h.endsWith(".alibaba.com"));}
 private JSONArray coordinates(JSONArray input,boolean toGcj)throws Exception{JSONArray out=new JSONArray();if(input==null)return out;if(input.length()>10000)throw new IllegalArgumentException("最多 10000 个路线点");for(int i=0;i<input.length();i++){JSONArray p=input.getJSONArray(i);double a=p.getDouble(0),o=p.getDouble(1);if(p.length()!=2||!Double.isFinite(a)||!Double.isFinite(o)||Math.abs(a)>85||Math.abs(o)>180)throw new IllegalArgumentException("地图坐标无效");double[] q=toGcj?CoordinateTransform.toGcj(a,o):CoordinateTransform.toWgs(a,o);out.put(new JSONArray().put(q[1]).put(q[0]));}return out;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);try{
  JSONObject input=new JSONObject(getIntent().getStringExtra("map"));JSONObject cfg=new JSONObject();JSONArray route=input.optJSONArray("points");selection=route==null?"[]":route.toString();cfg.put("points",coordinates(route,true)).put("ring",coordinates(input.optJSONArray("ring"),true)).put("loop",input.optBoolean("loop"));JSONArray checkpoints=new JSONArray(),raw=input.optJSONArray("checkpoints");if(raw!=null){if(raw.length()>10000)throw new IllegalArgumentException("点位过多");for(int i=0;i<raw.length();i++){JSONObject p=raw.getJSONObject(i);double a=p.getDouble("lat"),o=p.getDouble("lon");if(!Double.isFinite(a)||!Double.isFinite(o)||Math.abs(a)>85||Math.abs(o)>180)continue;double[] q=CoordinateTransform.toGcj(a,o);checkpoints.put(new JSONObject().put("position",new JSONArray().put(q[1]).put(q[0])).put("required",p.optBoolean("required")).put("name",p.optString("name","点位")));}}cfg.put("checkpoints",checkpoints);double[] center=CoordinateTransform.toGcj(34.16661610535,117.11362908317);cfg.put("center",new JSONArray().put(center[1]).put(center[0]));configuration=cfg.toString();
  ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=getAssets().open("live-map.js")){byte[] chunk=new byte[8192];int n;while((n=in.read(chunk))!=-1)bytes.write(chunk,0,n);}bootstrap="window.__routeConfig=JSON.parse("+JSONObject.quote(configuration).replace("<","\\u003c")+");"+bytes.toString("UTF-8");
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setPadding(8,4,8,4);root.addView(bar);Button cancel=new Button(this);cancel.setText("返回");bar.addView(cancel);cancel.setOnClickListener(v->finish());Button undo=new Button(this);undo.setText("撤销");bar.addView(undo);undo.setOnClickListener(v->web.evaluateJavascript("window.__routeUndo&&window.__routeUndo()",null));accept=new Button(this);accept.setText("使用路线");accept.setEnabled(false);bar.addView(accept);accept.setOnClickListener(v->{try{JSONArray selected=new JSONArray(selection);if(!ready||selected.length()<2)throw new Exception();setResult(RESULT_OK,new Intent().putExtra("points",selection));finish();}catch(Exception e){status.setText("请在地图上轻点至少两个途经点");}});
  status=new TextView(this);status.setPadding(16,5,16,8);status.setText("正在打开高德公开实时地图…");root.addView(status);web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));WebView.setWebContentsDebuggingEnabled(false);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);pageUserAgent=web.getSettings().getUserAgentString();web.addJavascriptInterface(new CoordinateBridge(),"RouteCoordinates");web.setWebViewClient(new WebViewClient(){
   @Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest req){Uri u=req.getUrl();return !("https".equals(u.getScheme())&&navigationHost(u.getHost()));}
   @Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest req){Uri u=req.getUrl();if(!"https".equals(u.getScheme())||!resourceHost(u.getHost()))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));if(req.isForMainFrame()&&"m.amap.com".equals(u.getHost())&&u.getPath()!=null&&u.getPath().startsWith("/share/index/")){try{HttpURLConnection c=(HttpURLConnection)new URL(u.toString()).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent",pageUserAgent);c.setRequestProperty("Accept-Encoding","identity");try{int code=c.getResponseCode();if(code!=200)throw new IOException("地图页面返回 "+code);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] chunk=new byte[16384];int n;while((n=in.read(chunk))!=-1){bytes.write(chunk,0,n);if(bytes.size()>6000000)throw new IOException("地图页面过大");}}String html=bytes.toString("UTF-8");java.util.regex.Pattern pattern=java.util.regex.Pattern.compile("(<script[^>]*src=[\"'][^\"']*webapi[.]amap[.]com/maps[^>]*></script>)",java.util.regex.Pattern.CASE_INSENSITIVE);java.util.regex.Matcher match=pattern.matcher(html);if(!match.find())throw new IOException("公开地图页面结构已变化，暂不能选点");String insert="<script>"+bootstrap.replace("</script","<\\/script")+"</script>";html=html.substring(0,match.end())+insert+html.substring(match.end());return new WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream(html.getBytes(StandardCharsets.UTF_8)));}finally{c.disconnect();}}catch(Exception e){runOnUiThread(()->status.setText("实时地图未就绪："+e.getMessage()));String error="<!doctype html><meta charset=utf-8><p>实时地图加载失败，请返回后重试。</p>";return new WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream(error.getBytes(StandardCharsets.UTF_8)));}}return null;}
   @Override public void onReceivedError(WebView w,WebResourceRequest req,WebResourceError e){if(req.isForMainFrame())status.setText("实时地图加载失败，请检查网络后重新打开");}
  });web.loadUrl("https://m.amap.com/share/index/lnglat="+center[1]+","+center[0]+"&name=Campus&src=uriapi&callnative=0&innersrc=uriapi");
 }catch(Exception e){new AlertDialog.Builder(this).setMessage("地图参数无法读取："+e.getMessage()).setPositiveButton("返回",(d,v)->finish()).show();}}
 public final class CoordinateBridge {
  @JavascriptInterface public void ready(){runOnUiThread(()->{ready=true;status.setText("实时高德地图 · 轻点选路线，拖动或双指缩放");try{accept.setEnabled(new JSONArray(selection).length()>=2);}catch(Exception ignored){}});}
  @JavascriptInterface public void update(String raw){try{if(raw==null||raw.length()>1500000)return;JSONArray input=new JSONArray(raw),out=new JSONArray();if(input.length()>10000)return;for(int i=0;i<input.length();i++){JSONArray p=input.getJSONArray(i);double o=p.getDouble(0),a=p.getDouble(1);if(p.length()!=2||!Double.isFinite(a)||!Double.isFinite(o)||Math.abs(a)>85||Math.abs(o)>180)return;double[] q=CoordinateTransform.toWgs(a,o);out.put(new JSONArray().put(q[0]).put(q[1]));}selection=out.toString();runOnUiThread(()->{accept.setEnabled(ready&&out.length()>=2);status.setText("实时高德地图 · 已选 "+out.length()+" 个途经点");});}catch(Exception ignored){}}
  @JavascriptInterface public void failed(){runOnUiThread(()->{ready=false;accept.setEnabled(false);status.setText("当前公开地图未完成初始化，请返回后重新打开");});}
 }
 @Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("RouteCoordinates");web.destroy();}super.onDestroy();}
}
